function replaceToolUsageBlock(source: string, replacement: string): string {
  const pattern = /## Tool Usage[\s\S]*?(?=\n## |\n# |$)/;
  if (!pattern.test(source)) {
    return source;
  }
  const normalized = replacement.trim();
  return source.replace(pattern, `${normalized}\n`);
}

